function getRecentIds(){const t=localStorage.getItem("recent");if(!t)return[];try{const e=JSON.parse(t);return Array.isArray(e)?e:[]}catch{return[]}}function hasRecentItems(){return getRecentIds().length>0}function loadRecentItems(t){const e=getRecentIds();if(e.length===0)return;const n=t.querySelector(".scrollable-line--list");if(!n)return;const r=new URLSearchParams;r.set("LIST",e.join(",")),fetch("/get-endpoints/getRecentItems?"+r.toString(),{method:"GET",credentials:"same-origin",headers:{Accept:"text/html"}}).then(i=>{if(!i.ok)throw new Error("HTTP "+i.status);return i.text()}).then(i=>{const o=document.createElement("div");o.innerHTML=i.trim(),n.innerHTML="",Array.from(o.childNodes).forEach(a=>n.appendChild(a)),typeof window.initScrollers=="function"&&window.initScrollers(n),typeof window.initLazyLoad=="function"&&window.initLazyLoad(n),typeof window.applyMobileButtonClass=="function"&&window.applyMobileButtonClass(n)}).catch(()=>{})}function showRecentSection(t){t.classList.remove("__hidden"),t.classList.add("__visible")}function hideRecentSection(t){if(!t.classList.contains("__visible")){t.classList.add("__hidden");return}t.classList.remove("__visible");const e=n=>{n.target!==t||n.propertyName!=="opacity"||(t.classList.add("__hidden"),t.removeEventListener("transitionend",e))};t.addEventListener("transitionend",e)}function updateRecentSectionVisibility(){const t=document.querySelector(".recent");t&&(hasRecentItems()?(loadRecentItems(t),showRecentSection(t)):hideRecentSection(t))}function initRecentSection(){updateRecentSectionVisibility(),window.addEventListener("storage",t=>{t.key==="recent"&&updateRecentSectionVisibility()})}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",initRecentSection):initRecentSection();
